data.minimal_example:
TableView.builder(
  columns: [
    const TableColumn(width: 56.0, freezePriority: 100),
    for (var i = 1; i < 100; i++) const TableColumn(width: 64),
  ],
  rowCount: 1048576,
  rowHeight: 56.0,
  rowBuilder: (context, row, contentBuilder) {
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => print('Row $row clicked'),
        child: contentBuilder(
          context,
          (context, column) => Text('$column'),
        ),
      ),
    );
  },
)
